#!/usr/bin/env bash
# instalar_btweb3b_zero.sh
# Instala btweb de la Pi 3 (con seccion chan_mobile) en la Raspberry Pi Zero. Un solo archivo.
#   1) paquetes: python3-flask, bluez, network-manager, python3-dbus, python3-gi
#   2) copia btweb original en /opt/btweb/btweb (backup previo en /root/backup_instalar_btweb)
#   3) escribe /opt/btweb/run.py y el servicio btweb.service (puerto 8080)
#   4) aplica la gestion WiFi (aplicar_12) sobre esa copia
#   5) arranca btweb
# Idempotente. Quitar el servicio: bash instalar_btweb_zero.sh --uninstall
set -euo pipefail

BASE=${BASE:-/opt/btweb}
BTDIR=$BASE/btweb
UNIT=${UNIT:-/etc/systemd/system/btweb.service}
DROPIN=${DROPIN:-/etc/systemd/system/btweb.service.d/mkbot-rw.conf}
BK=${BK:-/root/backup_instalar_btweb}
SYSTEMD=${SYSTEMD:-1}
PORT=${BTWEB_PORT:-8080}

[ "$(id -u)" -eq 0 ] || { echo "Ejecuta como root (sudo)"; exit 1; }

if [ "${1:-}" = "--uninstall" ]; then
  systemctl disable --now btweb 2>/dev/null || true
  rm -f "$UNIT"; rm -rf "$(dirname "$DROPIN")"
  systemctl daemon-reload
  echo "[ok] Servicio btweb quitado. Archivos en $BASE; borra con: rm -rf $BASE"
  exit 0
fi

# ---------- 1) paquetes ----------
if [ "$SYSTEMD" = 1 ]; then
  echo "== Instalando paquetes =="
  apt-get update -qq
  DEBIAN_FRONTEND=noninteractive apt-get install -y -qq \
    python3-flask python3-dbus python3-gi network-manager bluez >/dev/null
  systemctl is-active --quiet NetworkManager || { echo "!! NetworkManager no esta activo"; exit 1; }
  echo "[ok] paquetes listos"
fi

# ---------- 2) btweb original ----------
mkdir -p "$BASE"
if [ -d "$BTDIR" ] && [ ! -e "$BK/.hecho" ]; then
  mkdir -p "$BK"; cp -a "$BASE" "$BK/opt-btweb"; touch "$BK/.hecho"
  echo "[ok] Backup de $BASE en $BK"
fi
rm -rf "$BTDIR"
base64 -d <<'B64' | tar -xzf - -C "$BASE"

B64
echo "[ok] btweb (version de la 3B) extraido en $BTDIR"

# ---------- 3) run.py y servicio ----------
cat > "$BASE/run.py" <<'PYEOF'
#!/usr/bin/env python3
"""Arranque de btweb (panel Bluetooth y WiFi)."""
import os
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

from btweb import create_app  # noqa: E402

app = create_app()

if __name__ == "__main__":
    app.run(host=os.environ.get("BTWEB_HOST", "0.0.0.0"),
            port=int(os.environ.get("BTWEB_PORT", "8080")),
            threaded=True, debug=False, use_reloader=False)
PYEOF
cat > "$UNIT" <<UNITEOF
[Unit]
Description=btweb: panel Bluetooth y WiFi
After=bluetooth.service NetworkManager.service
Wants=bluetooth.service

[Service]
Type=simple
Environment=BTWEB_PORT=$PORT
ExecStart=/usr/bin/python3 $BASE/run.py
Restart=on-failure
RestartSec=5

[Install]
WantedBy=multi-user.target
UNITEOF
echo "[ok] $UNIT"

# ---------- 4) gestion WiFi (aplicar_12) ----------
W=$(mktemp)
trap 'rm -f "$W"' EXIT
